"""E2M3 as a hierarchical level program.

Generated by tools.emit_level_program.  Read this file the way you would
read any unfamiliar codebase: start at build_level, pick the area you care
about, and open only that builder.  Each room states its own outline in its
own coordinates, its own surface overrides, and its own sprites.

AUTHORITY.  E2M3.MAP is the exact source of truth and this file is not.
It is a re-expression of the decompiled hierarchy: the grouping is derived,
the names are interpreted, and the geometry is reproduced sector for sector
but recompiled, so wall ordering and portal indices are the compiler's own.

    exact: {"sectors": 340, "walls": 2808, "sprites": 454}
    regenerate: python -m tools.emit_level_program maps/blood/E2M3.MAP
"""

from __future__ import annotations

from bloodmap.levelprog import (
    Frame, LevelProgram, Style, native_detail,
)

#: Sectors the authoring model cannot express, and why.  They exist in
#: E2M3.MAP and are deliberately absent here rather than repaired.
NATIVE_ESCAPES = {
    217: 'self-intersection (partial_collinear_overlap)',
}

U = 384          # one player body width
PH = 0x1600      # one player standing height


def build_main_complex(parent) -> object:
    """main_complex (assembly:001): 327 sectors, 6929 player areas, 123 spaces.

    Named from measurement: the single navigation component holding 327 of the level's 340 sectors

    Origin is this area's own corner, so every outline below is local to it.
    """
    area = parent.assembly(
        'main_complex',
        frame=Frame(27136, -5888),
        style=Style(ceiling_picnum=2500, ceiling_shade=0, floor_picnum=2448, floor_shade=0, wall_picnum=2499, wall_shade=31),
    )
