def build_level() -> LevelProgram:
    """The whole level: 13 areas, 136 spaces, 339 of 340 sectors.

    1 sector(s) are in NATIVE_ESCAPES and are not built here.
    """
    level = LevelProgram(
        'e2m3', name='E2M3',
        style=Style(
            ceiling_picnum=2500,
            ceiling_shade=0,
            floor_picnum=2448,
            floor_shade=0,
            wall_picnum=2499,
            wall_shade=0,
            floor_z=0, clear_height=8 * PH,
        ),
    )
    build_main_complex(level)
    build_area_002(level)
    build_area_003(level)
    build_area_013(level)
    build_area_007(level)
    build_area_006(level)
    build_area_008(level)
    build_area_011(level)
    build_area_004(level)
    build_area_009(level)
    build_area_010(level)
    build_area_005(level)
    build_area_012(level)
    # Sectors the original overlaps in XY on purpose.  Build allows it;
    # the authoring compiler requires it to be said out loud.
    rooms = {room.node_id: room for room in level.rooms()}
    level.declare_stack(rooms['sector_003'], rooms['sector_040'], kind='partial_area_overlap')
    level.declare_stack(rooms['sector_040'], rooms['sector_042'], kind='full_containment_b_in_a')
    level.declare_stack(rooms['sector_040'], rooms['sector_043'], kind='partial_area_overlap')
    level.declare_stack(rooms['sector_040'], rooms['sector_044'], kind='full_containment_b_in_a')
    level.declare_stack(rooms['sector_040'], rooms['sector_045'], kind='full_containment_b_in_a')
    level.declare_stack(rooms['sector_040'], rooms['sector_046'], kind='full_containment_b_in_a')
    level.declare_stack(rooms['sector_040'], rooms['sector_327'], kind='full_containment_b_in_a')
    level.declare_stack(rooms['sector_040'], rooms['sector_328'], kind='full_containment_b_in_a')
    level.declare_stack(rooms['sector_040'], rooms['sector_329'], kind='partial_area_overlap')
    level.declare_stack(rooms['sector_041'], rooms['sector_043'], kind='partial_area_overlap')
    level.declare_stack(rooms['sector_041'], rooms['sector_329'], kind='partial_area_overlap')
    # The native kMarkerPlayerStart sprite's sector.
    level.set_start(
        next(room for room in level.rooms() if room.path().endswith('sector_286')),
        local=(0.188, 0.037), angle=256,
    )
    return level


if __name__ == '__main__':
    program = build_level()
    print(program.tree())
